"""Offline incident operations dashboard with no external dependencies."""
from html import escape
from pathlib import Path
import pandas as pd


def render_dashboard(summary:pd.DataFrame,path:str|Path)->None:
    if summary.empty:raise ValueError("Empty summary")
    total=int(summary.incidents.sum());resolved=int(summary.resolved.sum());overdue=int(summary.open_overdue.sum());backlog=total-resolved
    stats=[("INCIDENTS",f"{total:,}"),("RESOLVED",f"{resolved:,}"),("OPEN BACKLOG",f"{backlog:,}"),("OPEN OVERDUE",f"{overdue:,}")]
    cards="".join(f'<div class="card"><small>{escape(k)}</small><strong>{escape(v)}</strong></div>' for k,v in stats)
    bars="".join(f'<div class="bar"><span>{escape(x.category)}</span><div class="track"><div class="fill" style="width:{float(x.resolved_pct):.1f}%"></div></div><b>{float(x.resolved_pct):.1f}%</b></div>' for x in summary.itertuples())
    rows="".join(f'<tr><td>{escape(x.category)}</td><td>{int(x.incidents)}</td><td>{int(x.backlog)}</td><td>{int(x.open_overdue)}</td><td>{float(x.resolved_sla_pct):.1f}%</td></tr>' for x in summary.itertuples())
    html=f"""<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Incident Intelligence | Synthetic</title><style>:root{{--cyan:#4bd9fd;--violet:#ab90ff}}*{{box-sizing:border-box}}body{{margin:0;color:#eaf2ff;background:linear-gradient(125deg,#080f20,#1b1433);font:16px system-ui,Arial}}main{{max-width:1120px;margin:auto;padding:45px 22px}}h1{{font-size:clamp(28px,5vw,48px)}}h1 span{{color:var(--cyan)}}small,p,footer{{color:#b5c6df}}.intro{{color:var(--violet);letter-spacing:3px;font-size:13px}}.stats{{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px}}.card,.panel{{background:#13213ae6;border:1px solid #324362;border-radius:13px;padding:20px}}strong{{display:block;color:var(--cyan);font-size:33px;margin-top:12px}}.panel{{margin-top:22px}}.bar{{display:grid;grid-template-columns:95px 1fr 68px;gap:16px;margin:20px 0;align-items:center}}.track{{height:16px;background:#304363;border-radius:20px;overflow:hidden}}.fill{{height:100%;background:linear-gradient(90deg,var(--cyan),var(--violet))}}table{{width:100%;border-collapse:collapse}}td,th{{text-align:left;padding:12px;border-bottom:1px solid #42506b}}th{{color:var(--cyan)}}footer{{font-size:13px;margin:25px 0}}.scroll{{overflow:auto}}</style></head><body><main><div class="intro">MC // SYNTHETIC SERVICE INTELLIGENCE</div><h1>Operational Incident <span>Intelligence</span></h1><p>Deterministic incident resolution, backlog and SLA analysis as of 2026-04-01 00:00</p><div class="stats">{cards}</div><div class="panel"><h2>Resolution rate by category</h2>{bars}</div><div class="panel scroll"><h2>Incident control table</h2><table><thead><tr><th>CATEGORY</th><th>TOTAL</th><th>BACKLOG</th><th>OPEN OVERDUE</th><th>RESOLVED WITHIN SLA</th></tr></thead><tbody>{rows}</tbody></table></div><footer>All incidents and metrics are fictional; no real-world performance claims. SLA success rate is calculated among resolved incidents only; open backlog and overdue counts are shown separately to avoid hiding unresolved cases.</footer></main></body></html>"""
    f=Path(path);f.parent.mkdir(parents=True,exist_ok=True);f.write_text(html,encoding="utf-8")
